import { assertListeningCatalog, deepFreezeCatalog } from './listening-catalog-contract.js';

const ROLES = ['speaker_a', 'speaker_b', 'speaker_c', 'speaker_d', 'speaker_e', 'speaker_f'];
const VOICE_SLOTS = ['female_1', 'male_1', 'female_2', 'male_2', 'female_3', 'male_3'];

function matchingSet({ slug, title, topic, cefr, statements, speakers }) {
  return {
    id: `listening-pilot-v1.matching.${slug}`,
    revision: 1,
    type: 'matching',
    title,
    topic,
    cefr,
    provenance: 'original',
    audio: { path: `/audio/listening/listening-pilot-v1/matching/${slug}-r1.mp3` },
    script: speakers.map((speaker, index) => ({
      role: ROLES[index],
      voiceSlot: VOICE_SLOTS[index],
      text: speaker.text,
    })),
    task: {
      statements,
      answers: speakers.map((speaker) => speaker.answer),
      evidence: speakers.map((speaker) => ({
        statementIndex: speaker.answer,
        quote: speaker.quote,
        explanationRu: speaker.explanationRu,
      })),
    },
  };
}

function trueFalseSet({ slug, title, topic, cefr, voices, dialogue, items }) {
  return {
    id: `listening-pilot-v1.true-false.${slug}`,
    revision: 1,
    type: 'true_false',
    title,
    topic,
    cefr,
    provenance: 'original',
    audio: { path: `/audio/listening/listening-pilot-v1/true-false/${slug}-r1.mp3` },
    script: dialogue.map((text, index) => ({
      role: index % 2 === 0 ? 'speaker_a' : 'speaker_b',
      voiceSlot: voices[index % 2],
      text,
    })),
    task: {
      statements: items.map((item) => item.statement),
      answers: items.map((item) => item.answer),
      evidence: items.map((item) => ({
        answer: item.answer,
        quote: item.quote,
        explanationRu: item.explanationRu,
      })),
    },
  };
}

